// Golomb sequence G(n) is such unique non-decreasing sequence 
// of natural numbers, in which n appears exactly G(n) times
// 1 2 2 3 3 4 4 4 5 5 5 6 6 6 6 …
// Without caching execution time is huge due to repeated recursive calls
[Cache]
function G(n: int64): int64 := n = 1 ? 1 : 1 + G(n - G(G(n - 1)));

begin
  var n := 100000;
  (1..n).Sum(i -> G(i)).Print;
  Milliseconds.Print;
end.

