// Cloning graphical objects. 
// Graphical objects container. Nested containers
uses GraphABC,ABCObjects;

/// Create four graphical objects from one
procedure Four(var g: ObjectABC);
begin
  var w := 8*g.Width div 7;
  var f := ContainerABC.Create(0,0);
  f.Add(g);
  g := g.Clone;;
  g.moveon(w,0);
  g := g.Clone;
  g.moveon(0,w);
  g := g.Clone;
  g.moveon(-w,0);
  g := f;
end;

begin
  LockDrawingObjects;
  SetWindowSize(630,630);

  var g: ObjectABC := new SquareABC(0,0,14,clYellow);
  Four(g);
  Four(g);
  Four(g);
  Four(g);
  Four(g);
  UnLockDrawingObjects;
end.

// Moving graphical objects with mouse
uses ABCObjects,GraphABC;

var 
  ob: ObjectABC;
  sx,sy: integer;

procedure MyMouseDown(x,y,mb: integer);
begin
  ob := ObjectUnderPoint(x,y);
  if ob<>nil then
  begin
    sx := ob.Left - x;
    sy := ob.Top - y;
  end; 
end;

procedure MyMouseMove(x,y,mb: integer);
begin
  if ob<>nil then
    ob.Position := new Point(x+sx,y+sy);
end;

procedure MyMouseUp(x,y,mb: integer);
begin
  ob := nil;
end;


begin
  Window.Title := 'Move objects with mouse';
  for var i:=1 to 10 do
  begin
    var p := new PictureABC(Random(Window.Width-100),Random(Window.Height-100),'demo.bmp');
    p.Transparent := True;
  end;  
  OnMouseDown := MyMouseDown;
  OnMouseMove := MyMouseMove;
  OnMouseUp := MyMouseUp;
end.

